using System.Collections.Concurrent;
namespace AcSimulator.Api.Infrastructure;
public sealed class AppMetrics { private long requests;private long errors;private readonly ConcurrentDictionary<string,long> latencyBuckets=new();public void Observe(int status,long elapsedMs){Interlocked.Increment(ref requests);if(status>=500)Interlocked.Increment(ref errors);var bucket=elapsedMs<=100?"100":elapsedMs<=500?"500":elapsedMs<=1000?"1000":"inf";latencyBuckets.AddOrUpdate(bucket,1,(_,v)=>v+1);}public string Render()=>$"# HELP ac_http_requests_total Total requests\n# TYPE ac_http_requests_total counter\nac_http_requests_total {requests}\n# HELP ac_http_errors_total Server errors\n# TYPE ac_http_errors_total counter\nac_http_errors_total {errors}\n"+string.Join("\n",latencyBuckets.OrderBy(x=>x.Key).Select(x=>$"ac_http_latency_bucket{{le=\"{x.Key}\"}} {x.Value}"))+"\n";}
